SET TRANSACTION READ ONLY;SET LOCAL statement_timeout='100s';SET LOCAL ROLE needacabplus_shared_reader;
DO $$ DECLARE result jsonb;BEGIN
WITH b AS MATERIALIZED(SELECT "externalId",status,"bookingSource" source,"companyId",extract(year from "pickupDueTime")::int pickup_year,
CASE WHEN greatest(COALESCE(distance,0),COALESCE("systemDistance",0),COALESCE("meterDistance",0),COALESCE("meterDistanceMetres",0),COALESCE("gpsMeterDistance",0),COALESCE("estimatedDistance",0))>0 THEN 'positive' WHEN distance IS NULL AND "systemDistance" IS NULL AND "meterDistance" IS NULL AND "meterDistanceMetres" IS NULL AND "gpsMeterDistance" IS NULL AND "estimatedDistance" IS NULL THEN 'all_null' ELSE 'zero_or_nonpositive' END cohort,
 nullif(btrim("driverId"),'') IS NOT NULL driver_id,nullif(btrim("driverCallSign"),'') IS NOT NULL callsign,(nullif(btrim("driverId"),'') IS NOT NULL OR nullif(btrim("driverCallSign"),'') IS NOT NULL) driver,
 "dispatchedAt" IS NOT NULL dispatch,"acceptedAt" IS NOT NULL accepted,"arrivedAt" IS NOT NULL arrived,"pickedUpAt" IS NOT NULL pob,"completedAt" IS NOT NULL completion,
 "pickedUpAt">="dispatchedAt" AND "completedAt">="pickedUpAt" ordered_trip,
 price>0 price_positive,price=0 price_zero,price IS NULL price_missing,btrim("driverCallSign") SIMILAR TO '(9|4)%' hackney
FROM "Booking")
SELECT jsonb_build_object(
 'cohorts',(SELECT jsonb_agg(x) FROM(SELECT cohort,count(*) jobs,count(*)FILTER(WHERE driver_id) driver_id,count(*)FILTER(WHERE callsign) callsign,count(*)FILTER(WHERE driver) driver,count(*)FILTER(WHERE dispatch) dispatched,count(*)FILTER(WHERE accepted) accepted,count(*)FILTER(WHERE arrived) arrived,count(*)FILTER(WHERE pob) pob,count(*)FILTER(WHERE completion) completion,count(*)FILTER(WHERE driver AND dispatch AND pob AND completion) full_chain,count(*)FILTER(WHERE ordered_trip) ordered_trip,count(*)FILTER(WHERE price_positive) price_positive,count(*)FILTER(WHERE price_zero) price_zero,count(*)FILTER(WHERE price_missing) price_missing,count(*)FILTER(WHERE hackney) hackney FROM b GROUP BY cohort)x),
 'nonpositive_status',(SELECT jsonb_agg(x) FROM(SELECT status,count(*) jobs,count(*)FILTER(WHERE driver) driver,count(*)FILTER(WHERE dispatch) dispatched,count(*)FILTER(WHERE pob) pob,count(*)FILTER(WHERE completion) completion,count(*)FILTER(WHERE price_positive) price_positive FROM b WHERE cohort<>'positive' GROUP BY status ORDER BY 2 DESC)x),
 'nonpositive_source',(SELECT jsonb_agg(x) FROM(SELECT source,count(*) jobs,count(*)FILTER(WHERE driver) driver,count(*)FILTER(WHERE dispatch) dispatched,count(*)FILTER(WHERE pob) pob,count(*)FILTER(WHERE status='COMPLETED') completed_status FROM b WHERE cohort<>'positive' GROUP BY source ORDER BY 2 DESC)x),
 'furthest_stage',(SELECT jsonb_agg(x) FROM(SELECT cohort,CASE WHEN completion THEN 'completed_timestamp' WHEN pob THEN 'pob_timestamp' WHEN arrived THEN 'arrived_timestamp' WHEN dispatch THEN 'dispatch_timestamp' WHEN driver THEN 'driver_only' ELSE 'no_driver_or_stage' END stage,count(*) jobs FROM b GROUP BY 1,2 ORDER BY 1,2)x),
 'matched_source_status',(SELECT jsonb_agg(x) FROM(SELECT source,cohort,count(*) jobs,count(*)FILTER(WHERE driver) driver,count(*)FILTER(WHERE dispatch) dispatched,count(*)FILTER(WHERE pob) pob,count(*)FILTER(WHERE completion) completion,count(*)FILTER(WHERE price_positive) price_positive FROM b WHERE status='COMPLETED' AND source IN('FlaggedBooking','OperatorWeb','MobileApp') AND pickup_year IN(2025,2026) GROUP BY 1,2 ORDER BY 1,2)x)
) INTO result;RAISE NOTICE 'NO_POSITIVE_OPERATIONAL %',result;END $$;
